package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user. */
public class ValidateRemind {
    public void validate(@RequestBody RemindRequest request, Out<RemindInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        body.set(new RemindInput(request.user().trim()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Remind the loaded claim on the sheet's today: only an OPEN or PENDING claim, and only once per sheet-today. A
 *  reminder another user's change got to first is refused. */
public class SaveRemind {
    public void save(@Val Claim loaded, SheetRepository sheets, ClaimRepository repository, Out<ClaimResponse> saved)
            throws ClaimStatusNotAllowedException {
        if (!loaded.status().unsettled()) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be reminded; only an OPEN or PENDING one can.");
        }
        var today = sheets.today(loaded.sheetId());
        if (today == null) {
            throw new ClaimStatusNotAllowedException("Set the sheet's today before reminding a claim.");
        }
        if (today.equals(loaded.reminded())) {
            throw new ClaimStatusNotAllowedException("The claim was already reminded on " + today + ".");
        }
        if (!repository.remind(loaded, today)) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        saved.set(ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                loaded.date(), loaded.note(), loaded.status(), loaded.number(), loaded.settledDue(),
                loaded.openedBy(), loaded.stated(), loaded.statedDue(), loaded.corrects(), loaded.dueBy(),
                loaded.deferredUntil(), loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), today, loaded.ref(), loaded.tags()), List.of(),
                today));
    }
}
package net.officefloor.hq.app.claim;

/** A validated reminder: who is making it. */
public record RemindInput(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Record the stored reminder in the audit file, naming the claim like every claim line. */
public class AuditClaimReminded {
    public void audit(@Val RemindInput input, @Val Claim loaded, @Val ClaimResponse saved, PersonRepository people,
            Audit audit) {
        var person = people.find(loaded.sheetId(), loaded.personId());
        audit.record("REMIND sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (saved.number() != null ? " number=" + saved.number() : ""));
    }
}
